contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function: takes an arbitrary uint to quantify over inputs
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record balances before the call
        uint beforeOwnerBal = address(this).balance;
        uint beforeCBal = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: if the call did not revert then C's balance becomes zero
        // and this contract's balance is at least its previous balance (it receives any funds sent by selfdestruct)
        assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeOwnerBal));
    }
    receive() external payable {}
}

